window.pittzPlaygroundWallet={onConnectWallet:()=>{window.location.href='/#my-pittz'}};
const walletAddress=new URLSearchParams(window.location.search).get('wallet');
if(/^erd1[a-z0-9]{58}$/.test(walletAddress||'')){
 try{
  const response=await fetch('https://api.multiversx.com/accounts/'+walletAddress+'/nfts?size=10000',{signal:AbortSignal.timeout(15000)});
  if(!response.ok)throw Error('Wallet Pittz unavailable');
  const rows=await response.json();
  if(Array.isArray(rows))window.pittzPlaygroundWallet={...window.pittzPlaygroundWallet,address:walletAddress,nfts:rows.filter(n=>['PITTZ-1a4c2d','PITTZVICE-c3ec94'].includes(n.collection))};
 }catch{ /* Games remain available with random Pittz. */ }
}
